{"content":"import { createFileRoute, Link } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import { SlidersHorizontal, X } from "lucide-react";
import { ProductCard } from "@/components/site/ProductCard";
import { SearchBar } from "@/components/site/SearchBar";
import { CATEGORIES, buildFacets, getAllProducts, searchProducts } from "@/data/catalog";

interface ProductSearch {
  q: string;
  category: string;
  brand: string;
}

export const Route = createFileRoute("/products/")({
  validateSearch: (search: { q?: unknown; category?: unknown; brand?: unknown }): ProductSearch => ({
    q: typeof search.q === "string" ? search.q : "",
    category: typeof search.category === "string" ? search.category : "",
    brand: typeof search.brand === "string" ? search.brand : "",
  }),
  head: () => ({
    meta: [
      { title: "Product Catalog | Plumbing, HVAC, Pipe, Valves & Fittings | Pickrel Brothers" },
      {
        name: "description",
        content:
          "Search the Pickrel Brothers catalog by manufacturer, part number, size or category. Plumbing, HVAC, pipe, valves, fittings, pumps and industrial supplies in Dayton, Ohio.",
      },
      { property: "og:title", content: "Product Catalog | Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "Search wholesale plumbing, HVAC and industrial products by part number, brand or category.",
      },
    ],
  }),
  component: ProductsPage,
});

function ProductsPage() {
  const { q, category, brand } = Route.useSearch();
  const [facetFilters, setFacetFilters] = useState<Record<string, string[]>>({});
  const [showFilters, setShowFilters] = useState(false);
  const [sort, setSort] = useState("relevance");

  const base = useMemo(() => {
    let list = getAllProducts();
    if (category) list = list.filter((p) => p.category === category);
    if (brand) list = list.filter((p) => p.manufacturer === brand);
    if (q) list = searchProducts(q, list);
    return list;
  }, [q, category, brand]);

  const facets = useMemo(() => buildFacets(base), [base]);

  const results = useMemo(() => {
    let list = base.filter((p) =>
      Object.entries(facetFilters).every(
        ([k, vals]) => vals.length === 0 || vals.includes(p.facets[k] ?? ""),
      ),
    );
    if (sort === "price-asc") list = [...list].sort((a, b) => (a.price ?? 0) - (b.price ?? 0));
    if (sort === "price-desc") list = [...list].sort((a, b) => (b.price ?? 0) - (a.price ?? 0));
    if (sort === "name") list = [...list].sort((a, b) => a.name.localeCompare(b.name));
    return list;
  }, [base, facetFilters, sort]);

  function toggleFacet(key: string, value: string) {
    setFacetFilters((prev) => {
      const cur = prev[key] ?? [];
      return { ...prev, [key]: cur.includes(value) ? cur.filter((v) => v !== value) : [...cur, value] };
    });
  }

  const activeCount = Object.values(facetFilters).flat().length;

  return (
    <div className="container-page py-8">
      <nav aria-label="Breadcrumb" className="text-xs text-muted-foreground">
        <Link to="/" className="hover:text-sky">
          Home
        </Link>{" "}
        / <span className="text-foreground">Products</span>
        {category && <> / <span className="text-foreground">{category}</span></>}
      </nav>

      <h1 className="mt-3 font-display text-3xl font-bold uppercase text-navy">
        {category || brand || (q ? `Results for "${q}"` : "Product Catalog")}
      </h1>
      <p className="mt-1 text-sm text-muted-foreground">
        {results.length} product{results.length === 1 ? "" : "s"} — pricing shown is standard list.
        Account customers see contract pricing after sign-in.
      </p>

      <div className="mt-5 max-w-2xl">
        <SearchBar defaultValue={q} />
      </div>

      <div className="mt-6 flex flex-wrap items-center gap-2">
        {(category || brand || q) && (
          <Link
            to="/products"
            search={{ q: "", category: "", brand: "" }}
            className="inline-flex items-center gap-1 rounded-full bg-secondary px-3 py-1 text-xs font-semibold text-secondary-foreground hover:bg-sky hover:text-sky-foreground"
          >
            Clear search <X className="h-3 w-3" aria-hidden />
          </Link>
        )}
        <button
          type="button"
          onClick={() => setShowFilters((v) => !v)}
          className="inline-flex items-center gap-2 rounded-md border border-input px-3 py-1.5 text-xs font-semibold text-navy lg:hidden"
        >
          <SlidersHorizontal className="h-4 w-4" aria-hidden /> Filters{activeCount ? ` (${activeCount})` : ""}
        </button>
        <label className="ml-auto flex items-center gap-2 text-xs text-muted-foreground">
          Sort
          <select
            value={sort}
            onChange={(e) => setSort(e.target.value)}
            className="rounded-md border border-input bg-card px-2 py-1.5 text-xs text-foreground"
          >
            <option value="relevance">Relevance</option>
            <option value="name">Name A-Z</option>
            <option value="price-asc">Price low to high</option>
            <option value="price-desc">Price high to low</option>
          </select>
        </label>
      </div>

      <div className="mt-6 grid gap-6 lg:grid-cols-[240px_1fr]">
        <aside className={`${showFilters ? "block" : "hidden"} lg:block`}>
          <div className="rounded-md border border-border bg-card p-4 shadow-card">
            <h2 className="font-display text-sm font-bold uppercase tracking-wide text-navy">Categories</h2>
            <ul className="mt-3 space-y-1 text-sm">
              {CATEGORIES.map((c) => (
                <li key={c.slug}>
                  <Link
                    to="/products"
                    search={{ q, category: c.name === category ? "" : c.name, brand }}
                    className={`block rounded px-2 py-1 hover:bg-secondary ${
                      c.name === category ? "bg-secondary font-semibold text-sky" : "text-foreground"
                    }`}
                  >
                    {c.name}
                  </Link>
                </li>
              ))}
            </ul>

            {Object.entries(facets).map(([key, values]) => (
              <div key={key} className="mt-6">
                <h2 className="font-display text-sm font-bold uppercase tracking-wide text-navy">{key}</h2>
                <ul className="mt-2 space-y-1 text-sm">
                  {values.map((v) => (
                    <li key={v}>
                      <label className="flex cursor-pointer items-center gap-2 rounded px-2 py-1 hover:bg-secondary">
                        <input
                          type="checkbox"
                          className="accent-sky"
                          checked={(facetFilters[key] ?? []).includes(v)}
                          onChange={() => toggleFacet(key, v)}
                        />
                        <span>{v}</span>
                      </label>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </aside>

        <div>
          {results.length === 0 ? (
            <div className="rounded-md border border-border bg-card p-10 text-center shadow-card">
              <h2 className="font-display text-xl font-bold uppercase text-navy">No matches found</h2>
              <p className="mx-auto mt-2 max-w-md text-sm text-muted-foreground">
                We stock and source far more than what's online today. Tell us the part number or
                application and we'll locate it.
              </p>
              <Link
                to="/contact"
                className="mt-5 inline-block rounded-md bg-navy px-5 py-2.5 font-semibold text-navy-foreground hover:bg-navy-muted"
              >
                Just call — 937-461-5960
              </Link>
            </div>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
              {results.map((p) => (
                <ProductCard key={p.slug} product={p} />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
